60	import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
61	import { toIsoTimestamp } from "@/types/common";
62	
63	/**
64	 * Soft-delete conventions.
65	 *
66	 * Issues, projects and comments are never physically removed — they get an
67	 * `archived_at` timestamp. Repositories must express "live rows only" through
68	 * these helpers so the predicate stays in one place; a raw
69	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
70	 * drift this module prevents.
71	 */
72	
73	export function isArchived(row: SoftDeletable): boolean {
74	  return row.archivedAt !== null;
75	}
76	
77	export function isLive(row: SoftDeletable): boolean {
78	  return row.archivedAt === null;
79	}
80	
81	/** Filters an in-memory collection according to an `ArchiveScope`. */
82	export function applyArchiveScope<T extends SoftDeletable>(
83	  rows: readonly T[],
84	  scope: ArchiveScope = {},
85	): readonly T[] {
86	  return scope.includeArchived === true ? rows : rows.filter(isLive);
87	}
88	
89	/** True when the repository should add the `archived_at IS NULL` predicate. */
90	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
91	  return scope.includeArchived !== true;
92	}
