94	/** The column patch that archives a row. */
95	export function archivePatch(now: Date = new Date()): {
96	  archivedAt: IsoTimestamp;
97	  updatedAt: IsoTimestamp;
98	} {
99	  const stamp = toIsoTimestamp(now);
100	  return { archivedAt: stamp, updatedAt: stamp };
101	}
102	
103	/** The column patch that restores an archived row. */
104	export function restorePatch(now: Date = new Date()): {
105	  archivedAt: null;
106	  updatedAt: IsoTimestamp;
107	} {
108	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
