403	const CURSOR_SEPARATOR = "|";
404	
405	/**
406	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
407	 * sort value alongside the id is what lets `listX` resume from a stable point
408	 * even when two rows share a timestamp.
409	 */
410	export function encodeCursor(id: string, sortValue: string): string {
411	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
412	    "base64url",
413	  );
414	}
415	
416	export function decodeCursor(
417	  cursor: string,
418	): { id: string; sortValue: string } | null {
419	  let decoded: string;
420	  try {
421	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
422	  } catch {
423	    return null;
424	  }
425	
426	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
427	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
428	
429	  return {
430	    sortValue: decoded.slice(0, separatorAt),
431	    id: decoded.slice(separatorAt + 1),
432	  };
433	}
