/**
 * An invitation is pending while it has not been accepted, revoked or expired.
 * Only pending invitations hold a seat, so revoking one or letting it expire
 * frees its seat at once.
 */
function pendingPredicate(now: IsoTimestamp) {
  return and(
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, now),
  );
}

export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const now = toIsoTimestamp(new Date());
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(and(orgPredicate(invitations.orgId, orgId), pendingPredicate(now)))
    .get();
  return row?.value ?? 0;
}

/** The pending invitation for `email` in this org, if there is one. Emails compare without regard to case. */
export async function findPendingInvitationByEmail(
  orgId: OrgId,
  email: string,
): Promise<Invitation | null> {
  const now = toIsoTimestamp(new Date());
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        sql`lower(${invitations.email}) = ${email.toLowerCase()}`,
        pendingPredicate(now),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

export async function findInvitationById(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

